((SELECT trait_id FROM traits WHERE trait_name = 'plant_tolerance_calcicole'), 'calcicole', 'Plants are tolerant of basic soils, such as calcareous sands and limestone derived soils.'),
((SELECT trait_id FROM traits WHERE trait_name = 'plant_tolerance_calcicole'), 'calcifuge', 'Plants are intolerant of basic soils.'),
((SELECT trait_id FROM traits WHERE trait_name = 'competitive_stratum'), 'ground', 'Graminoids, herbs and ferns reaching maximum heights of c. 0.2-1 m.'),
((SELECT trait_id FROM traits WHERE trait_name = 'competitive_stratum'), 'mid', 'Shrubs reaching maximum heights of c. 1-2 m.'),
((SELECT trait_id FROM traits WHERE trait_name = 'competitive_stratum'), 'upper', 'Tall shrubs reaching maximum heights of c. 3-5 m.'),
((SELECT trait_id FROM traits WHERE trait_name = 'competitive_stratum'), 'post_fire_ephemeral', 'Taxa that avoid competition with other strata by rapidly completing their life cycle after fire; a sub-category of ''ground''.'),
((SELECT trait_id FROM traits WHERE trait_name = 'cotyledon_function'), 'foliaceous', 'Cotyledons are photosynthetic and function as leaves.'),
((SELECT trait_id FROM traits WHERE trait_name = 'cotyledon_function'), 'reserve', 'Cotyledons function as energy reserve organs.'),
((SELECT trait_id FROM traits WHERE trait_name = 'cotyledon_position'), 'cryptocotylar', 'A type of seed germination in which the cotyledons remain within the seed coat at germination.'),
