((SELECT trait_id FROM traits WHERE trait_name = 'seedling_germination_location'), 'hypogeal', 'Germinant with all cotyledons remaining belowground.'),
((SELECT trait_id FROM traits WHERE trait_name = 'dispersal_appendage'), 'aril', 'Fleshy outgrowth of a seed, that often attracts animals like birds or ants.'),
((SELECT trait_id FROM traits WHERE trait_name = 'dispersal_appendage'), 'bristles', 'Bristle-like projections. Trait value includes awns, which are slender, bristle-like projections in some grasses.'),
((SELECT trait_id FROM traits WHERE trait_name = 'dispersal_appendage'), 'bracts_and_glumes', 'When the bracts below the inflorescence are persistent and functional as dispersal appendages. This includes persistent glumes, the modified membranous bracts in the family Poaceae that surround the spikelet of a grass.'),
((SELECT trait_id FROM traits WHERE trait_name = 'dispersal_appendage'), 'elaiosome', 'Fleshy (often fatty) appendage on seeds that attracts ants.'),
((SELECT trait_id FROM traits WHERE trait_name = 'dispersal_appendage'), 'fleshy_reward', 'Broad term that includes a suite of appendages that provides a fleshy reward to attract dispersers; highest level of resolution available for some studies.'),
((SELECT trait_id FROM traits WHERE trait_name = 'dispersal_appendage'), 'floating_seed', 'Seed that is dispersed by floating on water.'),
((SELECT trait_id FROM traits WHERE trait_name = 'dispersal_appendage'), 'flotation_scales', 'Scales enhancing flotation, thereby assisting with dispersal.'),
((SELECT trait_id FROM traits WHERE trait_name = 'dispersal_appendage'), 'floral_parts', 'When some plant floral parts (the petals, sepals, or style) are persistent and aid in seed and fruit dispersal. This is a broad term not explicitly suggesting a dispersal mechanism.'),
((SELECT trait_id FROM traits WHERE trait_name = 'dispersal_appendage'), 'hairs', 'Modified hairs that aid in seed dispersal.'),
((SELECT trait_id FROM traits WHERE trait_name = 'dispersal_appendage'), 'hooks', 'A rear-facing point, as in a fish hook that aids in seed and fruit dispersal.'),
((SELECT trait_id FROM traits WHERE trait_name = 'dispersal_appendage'), 'inflated_parts', 'When some part of the seed, fruit, or associated tissues is inflated, aiding in seed or fruit dispersal.'),
((SELECT trait_id FROM traits WHERE trait_name = 'dispersal_appendage'), 'none', 'When a fruit and associated tissues lack any dispersal appendages. Includes exarillate and taxa with explicitly deciduous pappus.'),
((SELECT trait_id FROM traits WHERE trait_name = 'dispersal_appendage'), 'pappus', 'The calyx in Asteraceae that has been modified into bristles, hairs, scales or awns that are attached to the apex of the fruit. Taxa assigned this trait value have a persistent pappus that aids in dispersal, often, but not exclusively through wind dispersal. The pappus can also assist with flotation.'),
((SELECT trait_id FROM traits WHERE trait_name = 'dispersal_appendage'), 'plumose', 'Fruit, seed, style, or other floral component that is plumose and assists with dispersal.'),
((SELECT trait_id FROM traits WHERE trait_name = 'dispersal_appendage'), 'receptacle', 'Fleshy receptacle that aids in dispersal.'),
((SELECT trait_id FROM traits WHERE trait_name = 'dispersal_appendage'), 'sarcotesta', 'Fleshy seed coat that aids in dispersal.'),
((SELECT trait_id FROM traits WHERE trait_name = 'dispersal_appendage'), 'spines', 'Spines that aid in dispersal.'),
((SELECT trait_id FROM traits WHERE trait_name = 'dispersal_appendage'), 'tumbleweed', 'Plant growth form, whereby the aboveground plant component detaches from the roots and is readily rolled by wind across the ground, aiding in dispersal.'),
((SELECT trait_id FROM traits WHERE trait_name = 'dispersal_appendage'), 'wings', 'Referring to wing-like seed extensions that aid in wind dispersal.'),
((SELECT trait_id FROM traits WHERE trait_name = 'dispersal_appendage'), 'wing_or_plume', 'Broad term that includes a suite of appendages that aid in wind dispersal; highest level of resolution available for some studies.'),
((SELECT trait_id FROM traits WHERE trait_name = 'dispersal_syndrome'), 'anemochory', 'Diaspore is dispersed by wind.'),
((SELECT trait_id FROM traits WHERE trait_name = 'dispersal_syndrome'), 'anthrochory', 'Diaspore is dispersed by humans, either intentionally or unintentionally.'),
((SELECT trait_id FROM traits WHERE trait_name = 'dispersal_syndrome'), 'atelochory', 'Diaspore dispersal is prevented.'),
((SELECT trait_id FROM traits WHERE trait_name = 'dispersal_syndrome'), 'autochory', 'Diaspore is dispersed by methods originating from the parent plant or diaspore.'),
((SELECT trait_id FROM traits WHERE trait_name = 'dispersal_syndrome'), 'ballistic', 'Seeds are launched away from the plant by explosion as soon as the seed capsule opens.'),
((SELECT trait_id FROM traits WHERE trait_name = 'dispersal_syndrome'), 'barochory', 'Diaspores are dispersed without assistance.'),
((SELECT trait_id FROM traits WHERE trait_name = 'dispersal_syndrome'), 'chamaechory', 'Diaspore is dispersed by being rolled along ground surface by wind.'),
((SELECT trait_id FROM traits WHERE trait_name = 'dispersal_syndrome'), 'endozoochory', 'Diaspore is ingested by animals, either intentionally or accidentally, then transported before being deposited.'),
((SELECT trait_id FROM traits WHERE trait_name = 'dispersal_syndrome'), 'epizoochory', 'Diaspore is dispersed by accidentally attaching itself to the outside of an animal vector.'),
((SELECT trait_id FROM traits WHERE trait_name = 'dispersal_syndrome'), 'hydrochory', 'Diaspore is dispersed on the surface of water.'),
((SELECT trait_id FROM traits WHERE trait_name = 'dispersal_syndrome'), 'myrmecochory', 'Diaspores have elaiosomes (specialised nutritious appendages) that make them attractive for capture, transport and use by ants or related insects.'),
((SELECT trait_id FROM traits WHERE trait_name = 'dispersal_syndrome'), 'undefined', 'Dispersal mechanism unknown.'),
((SELECT trait_id FROM traits WHERE trait_name = 'dispersal_syndrome'), 'zoochory', 'Diaspore is dispersed by animals, by an undescribed mechanism.'),
