((SELECT trait_id FROM traits WHERE trait_name = 'dispersers'), 'cassowaries', 'Cassowaries, in contrast to smaller flying birds, are an important fruit dispersal agent.'),
((SELECT trait_id FROM traits WHERE trait_name = 'dispersers'), 'fish', 'Fish are an important fruit dispersal agent.'),
((SELECT trait_id FROM traits WHERE trait_name = 'dispersers'), 'floods', 'Floods are an important fruit dispersal agent.'),
