((SELECT trait_id FROM traits WHERE trait_name = 'life_history_ephemeral_class'), 'fire_ephemeral', 'Ephemeral plant that germinates and establishes following fire, where it is unknown if the plant is an obligate or facultative fire ephemeral.'),
