((SELECT trait_id FROM traits WHERE trait_name = 'parasitic'), 'hemiparasitic_facultative', 'Plant that is photosynthetic and can grow and reproduce without a host but augments its energy, mineral nutrition, and /or water supply through parasitism.'),
((SELECT trait_id FROM traits WHERE trait_name = 'parasitic'), 'holoparasitic', 'Plant that obtains all (or nearly all) of its energy through parasitism.'),
((SELECT trait_id FROM traits WHERE trait_name = 'parasitic'), 'parasitic', 'Plant that obtains some energy, mineral nutrition and/or water through parasitism. This term is used if a dataset does not specify if a plant is a hemiparasite or a holoparasite.'),
((SELECT trait_id FROM traits WHERE trait_name = 'parasitic'), 'not_parasitic', 'In the context of this trait, a plant that does not acquire energy, mineral nutrition, and/or water via haustoria connected to another plant. It can include species that form a symbiosis, including a parasitic interaction, with a fungal partner.'),
((SELECT trait_id FROM traits WHERE trait_name = 'parasitic'), 'root_parasitic', 'Parasitic plant whose haustoria penetrate the root of a host plant.'),
((SELECT trait_id FROM traits WHERE trait_name = 'parasitic'), 'stem_parasitic', 'Parasitic plant whose haustoria penetrate the stem of a host plant.'),
((SELECT trait_id FROM traits WHERE trait_name = 'plant_alternative_energy_and_nutrient_acquisition_strategy'), 'saprophyte', 'Plant that acquires nutrients from decaying biomass.'),
((SELECT trait_id FROM traits WHERE trait_name = 'plant_alternative_energy_and_nutrient_acquisition_strategy'), 'carnivorous', 'Plant that acquires some or most of its nutrients from animals or protozoa.'),
((SELECT trait_id FROM traits WHERE trait_name = 'plant_alternative_energy_and_nutrient_acquisition_strategy'), 'nutrient_mining', 'Plant that uses a specialised root structure, such as cluster roots, to mine nutrients inaccessible to other plant taxa.'),
((SELECT trait_id FROM traits WHERE trait_name = 'bark_photosynthetic_status'), 'non_photosynthetic_bark', 'Plant''s bark is not photosynthetic.'),
((SELECT trait_id FROM traits WHERE trait_name = 'bark_photosynthetic_status'), 'photosynthetic_bark', 'Plant''s bark is photosynthetic.'),
((SELECT trait_id FROM traits WHERE trait_name = 'photosynthetic_pathway'), 'c3', 'Plant using the ''standard'' photosynthetic pathway, where a 3-carbon compound is produced after the first stage in the photosynthetic pathway.'),
((SELECT trait_id FROM traits WHERE trait_name = 'photosynthetic_pathway'), 'c4', 'Plants in which the photosynthetic light-dependent reactions and the Calvin cycle are physically separated to reduce photorespiration.'),
((SELECT trait_id FROM traits WHERE trait_name = 'photosynthetic_pathway'), 'c3-c4', 'Taxa that shift between C3 and C4 photosynthesis.'),
((SELECT trait_id FROM traits WHERE trait_name = 'photosynthetic_pathway'), 'cam', 'Plants which display crassulacean acid metabolism.'),
((SELECT trait_id FROM traits WHERE trait_name = 'photosynthetic_pathway'), 'c3-cam', 'Taxa that shift between C3 and cam photosynthesis.'),
((SELECT trait_id FROM traits WHERE trait_name = 'photosynthetic_pathway'), 'c4-cam', 'Taxa that shift between C4 and cam photosynthesis.'),
((SELECT trait_id FROM traits WHERE trait_name = 'photosynthetic_pathway'), 'facultative_cam', 'Species that shifts between C3 and CAM photosynthesis depending on water availability.'),
((SELECT trait_id FROM traits WHERE trait_name = 'photosynthetic_pathway'), 'unknown', 'Photosynthetic pathway is unknown. (This trait value should be used if the photosynthetic pathway is assessed but unknown, not to record a lack of data.)'),
((SELECT trait_id FROM traits WHERE trait_name = 'plant_growth_form'), 'herb', 'A seed-bearing plant which does not have a woody above-ground stem; when available this term has been divided into more detailed terms.'),
((SELECT trait_id FROM traits WHERE trait_name = 'plant_growth_form'), 'subshrub', 'A plant that is only woody at the base, with the remainder of the stems regenerating yearly. This term is not meant to encompass short-lived plants that are only borderline woody.'),
((SELECT trait_id FROM traits WHERE trait_name = 'plant_growth_form'), 'shrub', 'A woody plant that is distinguished by NOT being a tree, due to one of more of the following characteristics, 1) they are less than 8 metres in height; 2) if a plant community includes trees, the shrubs are shorter than the surrounding trees and not part of the canopy; 3) in comparison to trees, the leaves are more distributed along the entire trunk; 4) the plant has multiple relatively narrow stems arising at or near ground level. The definition of `shrub` is complex, as there are many single-stemmed shrubs within Australia and many taxa that are described in the taxonomic literature as a shrub or small tree.'),
((SELECT trait_id FROM traits WHERE trait_name = 'plant_growth_form'), 'mallee', 'Refers to Eucalyptus species which are small trees that form a large lignotuber. They have multiple stems arising at or near ground level and regenerate from the lignotuber following fire.'),
((SELECT trait_id FROM traits WHERE trait_name = 'plant_growth_form'), 'tree', 'A tall, woody, perennial plant, usually with a single main trunk, and its leaves predominantly elevated above the ground surface.'),
((SELECT trait_id FROM traits WHERE trait_name = 'plant_growth_form'), 'graminoid', 'Herbaceous plant with a grass-like morphology that is within the order Poales. Taxa both with and without a tussock form are mapped to this term. This term is most frequently applied to three large monocot families, Poaceae, Cyperaceae, and Juncaceae, but the term could apply to other taxa within Poales with a grass-like morphology, including narrow, linear leaves and non-showy flowers, including Restionaceae, Centrolepidaceae, Anarthriaceae, and Ecdeiocoleaceae. Taxa outside Poales with a grass-like morphology should be designated as `herbs` and also have the term `tufted` mapped to the trait `stem_growth_habit`.'),
((SELECT trait_id FROM traits WHERE trait_name = 'plant_growth_form'), 'tussock', 'A subcategory of graminoid, which is a plant where many shoots from the basal meristem form prominent tufts.'),
((SELECT trait_id FROM traits WHERE trait_name = 'plant_growth_form'), 'graminoid_not_tussock', 'A subcategory of graminoid, indicating a plant which explicitly lacks a tussock morphology, with the leaves not growing in tufts.'),
((SELECT trait_id FROM traits WHERE trait_name = 'plant_growth_form'), 'hummock', 'Plant that grows as a dense mound up to 1 metre in height. The term generally applies only to species within the genera Triodia that form such mounds and these are considered a distinctive and uniquely Australian growth form.'),
((SELECT trait_id FROM traits WHERE trait_name = 'plant_growth_form'), 'basal_large', 'A plant whose leaves form a distinctly large basal tuft or rosette, including large acaulescent (non stemmed) monocots and cycads.'),
((SELECT trait_id FROM traits WHERE trait_name = 'plant_growth_form'), 'geophyte', 'Subcategory of herb, specifically referring to plants that survive the winter/dry season as an organ (rhizome, bulb, corm, or tuber) buried in dry soil, with all leaves dying back each year.'),
((SELECT trait_id FROM traits WHERE trait_name = 'plant_growth_form'), 'palmoid', 'Plant that bears a rosette-like canopy of typically large, often compound leaves atop a usually thick (pachycaulous), columnar, unbranched or little-branched stem. Palms, tree ferns, trunked cycads, trunked grass-trees, and Pandanus are mapped to this term.'),
((SELECT trait_id FROM traits WHERE trait_name = 'plant_growth_form'), 'climber', 'Plant that climbs up another plant''s stem or branches, rather than being able to support itself. Term used only if datasets do not specify if a climbing plant is herbaceous (a vine) or woody (a liana).'),
((SELECT trait_id FROM traits WHERE trait_name = 'plant_growth_form'), 'climber_herbaceous', 'Herbaceous plant that climbs up another plant''s stem or branches, rather than being able to support itself. This is usually synonymous with `vine`. Types of climbers (scrambling, twining) are captured under the trait `plant_climbing_mechanism`.'),
((SELECT trait_id FROM traits WHERE trait_name = 'plant_growth_form'), 'climber_woody', 'Woody or thick-stemmed (>2 cm) plant that climbs up another plant''s stem or branches, rather than being able to support itself. This is usually synonymous with `liana`. Woody climbers generally use hooks, tendrils, and/or adventitious roots to climb; the climbing mechanisms used by a taxon are captured under the trait `plant_climbing_mechanism`.'),
((SELECT trait_id FROM traits WHERE trait_name = 'plant_growth_form'), 'fern', 'A taxonomic grouping that includes acaulescent ferns; ferns are vascular plants that reproduce via spores and have neither seeds nor flowers.'),
((SELECT trait_id FROM traits WHERE trait_name = 'plant_growth_form'), 'lycophyte', 'A taxonomic grouping that includes quillworts, clubmosses, and spike mosses.'),
((SELECT trait_id FROM traits WHERE trait_name = 'plant_succulence'), 'succulent_stems', 'Stems are thick and fleshy.'),
((SELECT trait_id FROM traits WHERE trait_name = 'plant_succulence'), 'succulent_leaves', 'Leaves are thick and fleshy.'),
((SELECT trait_id FROM traits WHERE trait_name = 'plant_succulence'), 'succulent', 'A plant is designated as succulent but it is not specified which tissues are thick and fleshy.'),
((SELECT trait_id FROM traits WHERE trait_name = 'plant_succulence'), 'semi-succulent', 'A plant has tissues that are somewhat thick and fleshy, including many chenopods.'),
((SELECT trait_id FROM traits WHERE trait_name = 'plant_succulence'), 'not_succulent', 'Neither stems nor leaves are thick and fleshy.'),
((SELECT trait_id FROM traits WHERE trait_name = 'stem_growth_habit'), 'arborescent', 'Tree-like growth habit.'),
((SELECT trait_id FROM traits WHERE trait_name = 'stem_growth_habit'), 'erect', 'Stems that grow upright.'),
((SELECT trait_id FROM traits WHERE trait_name = 'stem_growth_habit'), 'caespitose', 'Multiple short-shoots arise from the base of the plant forming a dense tuft, as in a bunch-grass.'),
((SELECT trait_id FROM traits WHERE trait_name = 'stem_growth_habit'), 'cushion-forming', 'Multiple erect, short stems arise from the soil and are so tightly packed that they form dense, even, rounded canopy with no gaps.'),
((SELECT trait_id FROM traits WHERE trait_name = 'stem_growth_habit'), 'mat-forming', 'Multiple stems that are mostly horizontal and are densely packed but open enough that there are still a few gaps between them.'),
((SELECT trait_id FROM traits WHERE trait_name = 'stem_growth_habit'), 'tufted', 'Plant has a dense clump of leaves, either at the base of the plant or clusters of leaves growing close together higher on the plant. This term can refer to grasses, shrubs, or trees.'),
((SELECT trait_id FROM traits WHERE trait_name = 'stem_growth_habit'), 'creeping', 'Stem that creeps along the ground, rooting at nodes.'),
((SELECT trait_id FROM traits WHERE trait_name = 'stem_growth_habit'), 'decumbent', 'Stems whose bases lie flat on the ground but whose tips grow upward.'),
((SELECT trait_id FROM traits WHERE trait_name = 'stem_growth_habit'), 'prostrate', 'Stems lie flat on the ground but do not root at nodes.'),
((SELECT trait_id FROM traits WHERE trait_name = 'stem_growth_habit'), 'rosette', 'Plants whose leaves radiate from a central point at or near ground level.'),
((SELECT trait_id FROM traits WHERE trait_name = 'stem_growth_habit'), 'climbing', 'Stem that does not have a self-supporting structure and ascends by leaning on or attaching itself to surrounding vegetation or another substrate. Climbing mechanisms include tendrils, petioles, adventitious roots, scrambling, and twining and are distinguished between in the trait `plant_climbing_mechanism`.'),
((SELECT trait_id FROM traits WHERE trait_name = 'stem_growth_habit'), 'sprawling', 'Stem that sprawls across other plants or objects but lacks specialised climbing structures or mechanisms.'),
((SELECT trait_id FROM traits WHERE trait_name = 'stem_growth_habit'), 'rhizomatous', 'Plants with short horizontal underground stems from which shoots emerge.'),
((SELECT trait_id FROM traits WHERE trait_name = 'stem_growth_habit'), 'stoloniferous', 'Plants with long horizontal branches either slightly belowground or aboveground, that root at their nodes or tips, producing new plants.'),
((SELECT trait_id FROM traits WHERE trait_name = 'stem_growth_habit'), 'spreading', 'Plants with a notable horizontal extent, referring either to a broad tree canopy or a shrub or herb that spreads across the ground.'),
((SELECT trait_id FROM traits WHERE trait_name = 'stem_growth_habit'), 'floating', 'Plant where most of the leaves are floating on water.'),
((SELECT trait_id FROM traits WHERE trait_name = 'stem_growth_habit'), 'submerged', 'Plant where most of the leaves are submerged beneath the surface of a waterbody.'),
((SELECT trait_id FROM traits WHERE trait_name = 'stem_growth_habit'), 'dense', 'Plant with a high density of branches.'),
((SELECT trait_id FROM traits WHERE trait_name = 'stem_growth_habit'), 'compact', 'Plant with closely packed branches.'),
((SELECT trait_id FROM traits WHERE trait_name = 'stem_growth_habit'), 'bushy', 'Plant with much-branched branches.'),
((SELECT trait_id FROM traits WHERE trait_name = 'stem_growth_habit'), 'open', 'Plant with an open architecture of branches.'),
((SELECT trait_id FROM traits WHERE trait_name = 'stem_growth_habit'), 'spindly', 'Plants with weak, skinny branches.'),
((SELECT trait_id FROM traits WHERE trait_name = 'plant_climbing_mechanism'), 'adventitious_roots', 'Roots arising from stem nodes which cling to a host plant.'),
((SELECT trait_id FROM traits WHERE trait_name = 'plant_climbing_mechanism'), 'hooks', 'Curved stem outgrowths which allow climbers to cling to a host plant.'),
((SELECT trait_id FROM traits WHERE trait_name = 'plant_climbing_mechanism'), 'spines', 'Straight stem outgrowths (including true spines as well as thorns and prickles) which allow climbers to cling to a host plant.'),
((SELECT trait_id FROM traits WHERE trait_name = 'plant_climbing_mechanism'), 'tendrils', 'Modified leaves, petioles, or specialised axillary shoots that coil tightly, forming a specialised structure for climbing.'),
((SELECT trait_id FROM traits WHERE trait_name = 'plant_climbing_mechanism'), 'scrambling', 'Stem growth habit, where the plant stems are too weak to support themselves, and instead lean on and are supported by host vegetation. There are no specialised structures employed.'),
((SELECT trait_id FROM traits WHERE trait_name = 'plant_climbing_mechanism'), 'twining', 'Stem growth habit, where the plant stems twist or coil around a host plant to provide support.'),
((SELECT trait_id FROM traits WHERE trait_name = 'plant_growth_substrate'), 'epiphyte', 'A plant that grows upon another plant.'),
((SELECT trait_id FROM traits WHERE trait_name = 'plant_growth_substrate'), 'lithophyte', 'A plant that grows upon a rock.'),
((SELECT trait_id FROM traits WHERE trait_name = 'plant_growth_substrate'), 'terrestrial', 'A plant that grows on land, and generally referencing a plant that grows in soil.'),
((SELECT trait_id FROM traits WHERE trait_name = 'plant_growth_substrate'), 'semiaquatic', 'A plant that grows partially submerged in water or spends part of its life growing in water.'),
((SELECT trait_id FROM traits WHERE trait_name = 'plant_growth_substrate'), 'aquatic', 'A plant that grows in water.'),
((SELECT trait_id FROM traits WHERE trait_name = 'plant_growth_substrate'), 'marine', 'A plant that grows in the sea.'),
((SELECT trait_id FROM traits WHERE trait_name = 'plant_growth_substrate'), 'hemiepiphyte', 'A plant that spends part of its life cycle as an epiphyte, growing upon another plant.'),
((SELECT trait_id FROM traits WHERE trait_name = 'plant_type_by_resource_use'), 'hydrohalophyte', 'Tidal swamp or ''mangrove'' and coastal lagoon elements and temperate-zone salt-marsh taxa are classed together.'),
((SELECT trait_id FROM traits WHERE trait_name = 'plant_type_by_resource_use'), 'phreatophyte', 'Deep-rooted plants (usually trees) obtaining water from a deep underground source that may or may not be saline.'),
((SELECT trait_id FROM traits WHERE trait_name = 'plant_type_by_resource_use'), 'psammophile', 'Sand-loving plants commonly found in littoral strand or inland sandfields.'),
((SELECT trait_id FROM traits WHERE trait_name = 'plant_type_by_resource_use'), 'weedy', 'This inexact term is meant to indicate a high degree of adaptability to sites, and proven tendency toward aggressive colonization of either dry or wet sites, or rarely, both. In general, weeds invade and colonize highly disturbed sites or areas.'),
((SELECT trait_id FROM traits WHERE trait_name = 'plant_type_by_resource_use'), 'xerohalophyte', 'Plants adapted to inland salt desert and saline habitats.'),
((SELECT trait_id FROM traits WHERE trait_name = 'plant_type_by_resource_use'), 'xerophyte', 'Drought-tolerant and drought-adapted plants.'),
