((SELECT trait_id FROM traits WHERE trait_name = 'pollination_syndrome'), 'bird', 'Floral syndrome suggests flowers are bird-pollinated.'),
((SELECT trait_id FROM traits WHERE trait_name = 'pollination_syndrome'), 'butterfly', 'Floral syndrome suggests flowers are butterfly-pollinated.'),
