((SELECT trait_id FROM traits WHERE trait_name = 'pollination_syndrome'), 'wasp', 'Floral syndrome suggests flowers are wasp-pollinated.'),
((SELECT trait_id FROM traits WHERE trait_name = 'pollination_syndrome'), 'water', 'Floral syndrome suggests flowers are water-pollinated.'),
