((SELECT trait_id FROM traits WHERE trait_name = 'bud_bank_location'), 'apical_buds', 'Plants resprout from above-ground apical meristems. Also termed a caudex. Term refers to palm-like plants with aerial buds that resprout, including grass trees, palms, tree ferns, and pandanus.'),
((SELECT trait_id FROM traits WHERE trait_name = 'bud_bank_location'), 'basal_buds', 'Plants resprout from its base, with buds originating from stem tissue (e.g. lignotuber) and root tissue (root crown) not distinguished between. Most buds designated as being basal are likely to be resprouts from a lignotuber, but this trait value is used if the dataset reported `basal buds` rather than `basal stem buds` or `lignotuber`.'),
((SELECT trait_id FROM traits WHERE trait_name = 'bud_bank_location'), 'basal_stem_buds', 'Plants resprout from the base of the stem. Australian plants with basal stem buds usually have a lignotuber, documented in the trait `storage_organ`.'),
((SELECT trait_id FROM traits WHERE trait_name = 'bud_bank_location'), 'epicormic_buds', 'Plants resprout from the stem or trunk.'),
((SELECT trait_id FROM traits WHERE trait_name = 'bud_bank_location'), 'fleshy_underground_organ', 'Plants resprouts from buds on a fleshy underground organ that is a taproot tuber, bulb, corm, stem tuber, root tuber, or belowground caudex.'),
((SELECT trait_id FROM traits WHERE trait_name = 'bud_bank_location'), 'root_crown', 'Plants resprout from the root crown, the root tissue at the root-stem transition.'),
((SELECT trait_id FROM traits WHERE trait_name = 'bud_bank_location'), 'bud-bearing_root', 'Root buds produce vertical suckers (from root crown) or adventitious roots.'),
((SELECT trait_id FROM traits WHERE trait_name = 'bud_bank_location'), 'rhizome', 'Plants resprout from buds on a rhizome, where it is not specified if the rhizome is woody or non-woody.'),
((SELECT trait_id FROM traits WHERE trait_name = 'bud_bank_location'), 'rhizome_woody', 'Plants resprout from buds on a woody rhizome.'),
((SELECT trait_id FROM traits WHERE trait_name = 'bud_bank_location'), 'rhizome_non_woody', 'Plants resprout from buds on a fleshy rhizome, rhizophore, or fibrous rhizome.'),
((SELECT trait_id FROM traits WHERE trait_name = 'bud_bank_location'), 'stem_buds', 'Plants resprout from stem buds; this trait value is separate to epicormic buds.'),
((SELECT trait_id FROM traits WHERE trait_name = 'bud_bank_location'), 'stem_tuber', 'Plants resprout from buds on a stem tuber.'),
((SELECT trait_id FROM traits WHERE trait_name = 'bud_bank_location'), 'stolon', 'Horizontal branches (stems) resprout from the base of the plant.'),
((SELECT trait_id FROM traits WHERE trait_name = 'bud_bank_location'), 'underground_buds', 'Plants that resprout from underground organ, but the type of organ isn''t specified.'),
((SELECT trait_id FROM traits WHERE trait_name = 'bud_bank_location'), 'none', 'Plants lack regenerative buds.'),
((SELECT trait_id FROM traits WHERE trait_name = 'storage_organ'), 'bulb', 'Below ground storage organ derived from stem and usually leaf tissue.'),
((SELECT trait_id FROM traits WHERE trait_name = 'storage_organ'), 'corm', 'Below ground storage organ that is a short, rounded, vertical, fleshy, underground stem.'),
((SELECT trait_id FROM traits WHERE trait_name = 'storage_organ'), 'caudex', 'Swollen stem that usually functions in water storage, although the term can also apply to below ground structures or to swollen roots.'),
((SELECT trait_id FROM traits WHERE trait_name = 'storage_organ'), 'fleshy_underground_organ', 'Plants that use fleshy, generally underground organs (swellings) to regenerate, but the type of organ is not specified; examples include corms, tubers, bulbs, and caudex.'),
((SELECT trait_id FROM traits WHERE trait_name = 'storage_organ'), 'lignotuber', 'Swollen woody structures are located at the transition between the stem base and root crown of woody shrubs, mallees and small trees, and are formed from stem tissues. Buds are located over the entire structure. No colonisation ability.'),
((SELECT trait_id FROM traits WHERE trait_name = 'storage_organ'), 'pseudobulb', 'An above ground storage organ present in many terrestrial and epiphytic orchids created throough the thickening of the stem between leaf nodes.'),
((SELECT trait_id FROM traits WHERE trait_name = 'storage_organ'), 'rhizome', 'A type of continually growing or creeping underground stem, but it is not specified if the rhizome is woody or non-woody.'),
((SELECT trait_id FROM traits WHERE trait_name = 'storage_organ'), 'rhizome_woody', 'A type of continually growing or creeping woody underground stem.'),
((SELECT trait_id FROM traits WHERE trait_name = 'storage_organ'), 'rhizome_fleshy', 'A type of continually growing or creeping fleshy, non-woody underground stem.'),
((SELECT trait_id FROM traits WHERE trait_name = 'storage_organ'), 'rhizome_fibrous', 'A type of continually growing or creeping fibrous, non-woody underground stem.'),
((SELECT trait_id FROM traits WHERE trait_name = 'storage_organ'), 'root_tuber', 'A swollen root the stores nutrients, carbohydrates and water.'),
((SELECT trait_id FROM traits WHERE trait_name = 'storage_organ'), 'stem_tuber', 'A swollen underground stem that stores nutrients, carbohydrates and water.'),
((SELECT trait_id FROM traits WHERE trait_name = 'storage_organ'), 'storage_organ', 'Plant has a storage organ, but the type is unknown.'),
((SELECT trait_id FROM traits WHERE trait_name = 'storage_organ'), 'tuber', 'A swollen underground organ that stores nutrients, carbohydrates and water, where it is not specified if the tuber develops from root or stem tissue.'),
((SELECT trait_id FROM traits WHERE trait_name = 'storage_organ'), 'no_storage_organ', 'No storage organ present'),
((SELECT trait_id FROM traits WHERE trait_name = 'resprouting_capacity_non_fire_disturbance'), 'resprouts_non_fire_disturbance', 'Plants that are known to be fire-killed, but have the ability to resprout following a disturbance other than fire that causes 100% leaf loss.'),
((SELECT trait_id FROM traits WHERE trait_name = 'resprouting_capacity_non_fire_disturbance'), 'resprouts_after_cyclone', 'Plants are able to resprout following 100% leaf loss in a cyclone.'),
((SELECT trait_id FROM traits WHERE trait_name = 'resprouting_capacity_non_fire_disturbance'), 'resprouts_after_drought', 'Plants are able to resprout following 100% leaf loss during a drought.'),
((SELECT trait_id FROM traits WHERE trait_name = 'clonal_spread_mechanism'), 'aboveground_clonal', 'Vegetative buds or plant fragments that can disperse and produce new plants (including axillary buds, bulbils and turions).'),
((SELECT trait_id FROM traits WHERE trait_name = 'clonal_spread_mechanism'), 'adventitious_roots', 'Adventitious roots can form at nodes on the main roots or aboveground from nodes on stems.'),
((SELECT trait_id FROM traits WHERE trait_name = 'clonal_spread_mechanism'), 'bulb', 'Below ground storage organ derived from stem (and sometimes leaf) tissue, that divides into new individuals.'),
((SELECT trait_id FROM traits WHERE trait_name = 'clonal_spread_mechanism'), 'belowground_clonal', 'Plants use an unspecified underground organ for clonal spread.'),
((SELECT trait_id FROM traits WHERE trait_name = 'clonal_spread_mechanism'), 'corm', 'Below ground organ derived from stem tissue that can function either for vegetative spread or to regenerate following a disturbance.'),
((SELECT trait_id FROM traits WHERE trait_name = 'clonal_spread_mechanism'), 'rhizome', 'Plant has an underground stem that has stem buds and forms adventitious roots at nodes; this stem may be woody or non-woody. Rhizomes are both a mechanism for vegetative spread and a strategy to survive fire.'),
((SELECT trait_id FROM traits WHERE trait_name = 'clonal_spread_mechanism'), 'root_buds', 'Root buds that produce vertical suckers.'),
((SELECT trait_id FROM traits WHERE trait_name = 'clonal_spread_mechanism'), 'root_tuber', 'A swollen root that functions as a storage organ and has buds that allow clonal growth.'),
((SELECT trait_id FROM traits WHERE trait_name = 'clonal_spread_mechanism'), 'stem_tuber', 'A swollen underground stem that functions as a storage organ and has buds that allow clonal growth.'),
((SELECT trait_id FROM traits WHERE trait_name = 'clonal_spread_mechanism'), 'stolon', 'Plants having horizontal branches (stems) from the base of the plant that produce new plants from buds at its tip or nodes.'),
((SELECT trait_id FROM traits WHERE trait_name = 'clonal_spread_mechanism'), 'viviparous', 'Plant produces clonal offspring that grow while still attached to the parent plant.'),
((SELECT trait_id FROM traits WHERE trait_name = 'clonal_spread_mechanism'), 'non_clonal', 'Plant does not display clonal growth.'),
((SELECT trait_id FROM traits WHERE trait_name = 'root_system_classification'), 'type_i', 'The primary root is fibrous or fleshy and is relatively long; mesophytic.'),
((SELECT trait_id FROM traits WHERE trait_name = 'root_system_classification'), 'type_ii', 'The primary root is relatively short and is fibrous. Roots are well branched in a dry habitat but branch little in one that is wet.'),
((SELECT trait_id FROM traits WHERE trait_name = 'root_system_classification'), 'type_iii', 'The primary root is usually long and fibrous. The first order lateral roots are well branched and are usually short; they are rather evenly distributed along the primary root; xerophytic.'),
((SELECT trait_id FROM traits WHERE trait_name = 'root_system_classification'), 'type_iv', 'The primary root is usually long and slender like that of Type II. The first order lateral roots are well branched. Those closest to the surface of the ground, or not far below, are relatively long; xerophytic and mesophytic.'),
((SELECT trait_id FROM traits WHERE trait_name = 'root_system_classification'), 'type_v', 'The primary root is divided-forked or branched-and fibrous, and with few first order lateral roots, or, in age, apparently with none; xerophytic.'),
((SELECT trait_id FROM traits WHERE trait_name = 'root_system_classification'), 'type_vi', 'The primary root is usually as in Type V. The first order lateral roots are mostly on the upper portion of the primary root and are thus relatively superficial; xerophytic or in well aerated sandy soil where the rainfall is not light.'),
((SELECT trait_id FROM traits WHERE trait_name = 'root_system_classification'), 'type_vii', 'Adventitious roots that are in one group and arise on a short horizontal, or vertical, axis of the shoot. They are fibrous or fleshly; mesophytic and hydrophytic.'),
((SELECT trait_id FROM traits WHERE trait_name = 'root_system_classification'), 'type_viii', 'Adventitious roots that are in one group and are fibrous and fleshy, or fibrous and thick. The fibrous adventitious roots are absorbing-anchoring roots and are usually with laterals to the second order; meophytic.'),
((SELECT trait_id FROM traits WHERE trait_name = 'root_system_classification'), 'type_ix', 'Adventitious roots that arise on the aerial stem and branches of some herbaceous taxa, shrubs, and trees; on creepers, vines, and runners; and on subterranean rhizomes and stolons.'),
((SELECT trait_id FROM traits WHERE trait_name = 'root_structure'), 'arbuscular_mycorrhizal', 'Symbiosis in which the mycorrhizal fungi does penetrate the cortex cells of the plant roots and its hyphae form arbuscules and vesicles inside the plant root; endomycorrhizal, AM, VAM.'),
((SELECT trait_id FROM traits WHERE trait_name = 'root_structure'), 'carnivorous', 'Plant has non-mycorrhizal carnivorous root.'),
((SELECT trait_id FROM traits WHERE trait_name = 'root_structure'), 'cluster_roots', 'Non-proteoid taxa with cluster roots.'),
((SELECT trait_id FROM traits WHERE trait_name = 'root_structure'), 'coiling_vam', 'Associations that spread predominantly by intracellular hyphal coils within roots.'),
((SELECT trait_id FROM traits WHERE trait_name = 'root_structure'), 'dauciform_root', 'A type of cluster root found in the family Cyperaceae.'),
((SELECT trait_id FROM traits WHERE trait_name = 'root_structure'), 'ectomycorrhizal', 'Symbiosis in which the mycorrhizal fungi does not penetrate the cortex cells of the plant roots.'),
((SELECT trait_id FROM traits WHERE trait_name = 'root_structure'), 'ericoid_mycorrhizal', 'A form of arbuscular mycorrhizal relationship only found on plants in the order Ericales. The fungi''s hyphae penetrate the plant root but do not form arbuscules.'),
((SELECT trait_id FROM traits WHERE trait_name = 'root_structure'), 'fine_roots', 'Particularly fine roots for nutrient uptake.'),
((SELECT trait_id FROM traits WHERE trait_name = 'root_structure'), 'haustorium', 'A highly modified stem or root of a parasitic plant, such as mistletoe , or a specialized branch or tube originating from a hairlike filament (hypha) of a fungus. The haustorium penetrates the tissues of a host and absorbs nutrients and water.'),
((SELECT trait_id FROM traits WHERE trait_name = 'root_structure'), 'hemiparasitic_root', 'Plant with a partially parasitic root.'),
((SELECT trait_id FROM traits WHERE trait_name = 'root_structure'), 'long_root_hairs', 'Plant with specialised long root hairs.'),
((SELECT trait_id FROM traits WHERE trait_name = 'root_structure'), 'mycorrhizal', 'Plant mycorrhizal but type not specified.'),
((SELECT trait_id FROM traits WHERE trait_name = 'root_structure'), 'non_mycorrhizal', 'Plants lacking a mycorrhizal symbiont.'),
((SELECT trait_id FROM traits WHERE trait_name = 'root_structure'), 'orchid_mycorrhizal', 'A mycorrhizal relationship specific to orchid taxa, and for most orchids, essential for seedlings to establish.'),
((SELECT trait_id FROM traits WHERE trait_name = 'root_structure'), 'parasitic_root', 'Plant with a parasitic root.'),
((SELECT trait_id FROM traits WHERE trait_name = 'root_structure'), 'proteoid_root', 'Also known as cluster roots, are plant roots that form clusters of closely spaced short lateral rootlets and aid in nutrient upake in nutrient-poor soils; common in members of the family Proteaceae but present in other families as well.'),
((SELECT trait_id FROM traits WHERE trait_name = 'root_structure'), 'root_hairs', 'Plant with specialised root hairs.'),
((SELECT trait_id FROM traits WHERE trait_name = 'root_structure'), 'sand-binding', 'Persistent sheaths of sand that form around the roots of taxa in the families Restionaceae, Cyperaceae, Haemodoraceae, and Lomandraceae in western Australia. Assumed to function in nutrient uptake.'),
((SELECT trait_id FROM traits WHERE trait_name = 'root_structure'), 'saprophyte', 'Plant that acquires nutrients from decaying biomass.'),
((SELECT trait_id FROM traits WHERE trait_name = 'root_structure'), 'subepidermal_mycorrhizal', 'Mycorrhizae where hyphae grow in a cavity under epidermal cells. Only in the genus Thysanotus (family Laxmaniaceae).'),
((SELECT trait_id FROM traits WHERE trait_name = 'root_structure'), 'unknown', 'Root structures unknown.'),
