((SELECT trait_id FROM traits WHERE trait_name = 'plant_tolerance_salt'), 'halophyte', 'Plants that complete their life cycle in a salty environment; many survive in seawater or even higher concentrations of salt.'),
((SELECT trait_id FROM traits WHERE trait_name = 'plant_tolerance_salt'), 'halophyte_moderate', 'Plant that is moderately tolerant of soil salinity/sodicity.'),
((SELECT trait_id FROM traits WHERE trait_name = 'plant_tolerance_salt'), 'hydrohalophyte', 'Tidal swamp or ''mangrove'' and coastal lagoon elements and temperate-zone salt-marsh taxa are classed together.'),
((SELECT trait_id FROM traits WHERE trait_name = 'plant_tolerance_salt'), 'salt_spray_tolerant', 'Plant that is tolerant of salt spray (typically inhabiting near-coastal environments).'),
((SELECT trait_id FROM traits WHERE trait_name = 'plant_tolerance_salt'), 'salinity_tolerance_undefined', 'Plant''s ability to tolerate salt is unknown.'),
((SELECT trait_id FROM traits WHERE trait_name = 'plant_tolerance_salt'), 'xerohalophyte', 'Plants adapted to inland salt desert and saline habitats.'),
((SELECT trait_id FROM traits WHERE trait_name = 'seed_shape'), 'comma-shaped', 'A seed displaying a single arc of curvature, such that it bilaterally symmetrical.'),
((SELECT trait_id FROM traits WHERE trait_name = 'seed_shape'), 'conical', 'Cone-shaped, with a broad flat base and narrow apex; turbinate refers to the inverse shape.'),
((SELECT trait_id FROM traits WHERE trait_name = 'seed_shape'), 'cuneate', 'A 3-dimensional shape that is wedge-shaped or boat-shaped.'),
