((SELECT trait_id FROM traits WHERE trait_name = 'seed_shape'), 'discoid', 'A subset of cylinder, a shape with a flat, circular or elliptical top and bottom, linked by a curved surface, where the length of the curved surface is much shorter than the cross-section of the flat surfaces.'),
((SELECT trait_id FROM traits WHERE trait_name = 'seed_shape'), 'ellipsoid', 'A 3-dimensional shape that is elliptic in long section and circular in cross section; length:width ratio between 2:1 and 3:2.'),
((SELECT trait_id FROM traits WHERE trait_name = 'seed_shape'), 'ellipsoid_flattened', 'A 3-dimensional shape that is elliptic in long section and and laterally compressed/flattened such that it is non-circular in cross section; length:width ratio between 2:1 and 3:2.'),
