((SELECT trait_id FROM traits WHERE trait_name = 'seed_shape'), 'hemispheric_flattened', 'A 3-dimensional shape that is a laterally compressed/flattened half-sphere or globe; shape has a flat base, a domed top, and is elliptical in cross-section.'),
((SELECT trait_id FROM traits WHERE trait_name = 'seed_shape'), 'lenticular', 'Shaped like a biconvex lens and circular in cross section; shaped like a lentil.'),
((SELECT trait_id FROM traits WHERE trait_name = 'seed_shape'), 'orbicular', 'A poorly defined term that remains in AusTraits only as a placeholder; it appears to be used as both globoid (spherical) and lenticular by different authors.'),
((SELECT trait_id FROM traits WHERE trait_name = 'seed_shape'), 'ovoid', 'A 3-dimensional shape that is egg-shaped in long section and circular in cross section. Term as used in AusTraits includes variants on egg-shaped including pyriform (pear-shaped) and obovoid (inversely egg-shaped)'),
((SELECT trait_id FROM traits WHERE trait_name = 'seed_shape'), 'ovoid_elongated', 'A 3-dimensional shape that is egg-shaped in long section and circular in cross section, where the length dimension is much longer than the width/height dimensions. Term as used in AusTraits includes specific shapes club-shaped (clavate/obclavate) and tear-shaped (lachrimiform).'),
((SELECT trait_id FROM traits WHERE trait_name = 'seed_shape'), 'ovoid_flattened', 'A 3-dimensional shape that is egg-shaped in long section and laterally compressed/flattened such that is non-circular in cross section.'),
((SELECT trait_id FROM traits WHERE trait_name = 'seed_shape'), 'polyhedral', 'A 3-dimensional shape with distinct, fairly flat faces and edges; includes prisms and tetrahedral shaped seeds.'),
((SELECT trait_id FROM traits WHERE trait_name = 'seed_shape'), 'polyhedral_elongated', 'A 3-dimensional shape with distinct, fairly flat faces and edges, where the length dimension is much longer than the width/height dimensions; includes elongate prisms and elongate tetrahedral shaped seeds.'),
((SELECT trait_id FROM traits WHERE trait_name = 'seed_shape'), 'polyhedral_inflated', 'A 3-dimensional shape with distinct faces and edges but the faces tend to bulge outwards.'),
